use super::*;

/// Where you are, and what it asks of you.
///
/// Every figure prints WITH its source, because the standing caveat — nothing here has been checked
/// against those sources by a person — is only actionable if the source is on the same line.
pub fn render_where(
    chain: &[jurisdiction::Place],
    obligations: &[jurisdiction::Obligation],
    sales: &Result<(i64, Vec<jurisdiction::Rate>), String>,
    income: &[jurisdiction::Rate],
    as_of: &str,
) -> String {
    let mut out = String::new();
    let names: Vec<&str> = chain.iter().rev().map(|p| p.name).collect();
    out.push_str(&format!("{}\n", names.join(" › ")));
    out.push_str(&format!("as of {as_of}\n\n"));

    out.push_str("  Rates\n");
    match sales {
        Ok((bps, found)) => {
            out.push_str(&format!("    sales tax        {:>7}   ", format_bps(*bps)));
            out.push_str(&format!("{}\n", found.iter().map(|r| format!("{} {}", r.place, format_bps(r.bps))).collect::<Vec<_>>().join(" + ")));
        }
        Err(e) => out.push_str(&format!("    sales tax        REFUSED — {e}\n")),
    }
    if income.is_empty() {
        out.push_str("    income tax       NOT KNOWN for this date — a rate here would be a guess, and this is an input to a return\n");
    } else {
        for r in income {
            out.push_str(&format!("    income tax       {:>7}   {}{}\n", format_bps(r.bps), r.place, r.to.map(|t| format!(" (through {t})")).unwrap_or_default()));
        }
    }
    out.push('\n');

    if !obligations.is_empty() {
        out.push_str("  What this place requires\n");
        for o in obligations {
            let cost = match o.cost_minor {
                Some(0) => "free".to_string(),
                Some(c) => crate::money::format_minor(c),
                // NOT rendered as a number, because it is not one.
                None => "varies".to_string(),
            };
            let due = jurisdiction::next_due(o.cadence, as_of).map(|d| format!("next {d}")).unwrap_or_else(|| "once".to_string());
            out.push_str(&format!("    {:<32} {:>9}  {}\n", clip(o.name, 31), cost, due));
            out.push_str(&format!("      {}\n", o.required_when));
            out.push_str(&format!("      → {}\n", o.authority));
        }
        out.push('\n');
    }

    out.push_str("  NOTHING HERE HAS BEEN CHECKED AGAINST ITS SOURCE BY A PERSON, and rates change on a\n");
    out.push_str("  schedule. Run `bsc fin where sources` and verify before anything is filed. This is not\n");
    out.push_str("  tax advice and it files nothing.\n");
    out
}
